const root = scope && scope.payload && typeof scope.payload === 'object' ? scope.payload : scope;
// True only for the update that moved the work item into the approved status, never for later edits of an
// approved work item and never for iHub's own field write-back.
const items = root && root.changelog && root.changelog.items;
if (!Array.isArray(items)) return 'false';
const approved = "{{{_flow.APPROVED_STATUS_NAME}}}".trim().toLowerCase();
return items.some((entry) => String(entry.field || entry.fieldId || '').toLowerCase() === 'status'
  && String(typeof entry.toString === 'string' ? entry.toString : '').trim().toLowerCase() === approved) ? 'true' : 'false';

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// With REQUEST_TYPE_NAME empty every request of the configured work item type qualifies.
const wanted = "{{{_flow.REQUEST_TYPE_NAME}}}".trim().toLowerCase();
if (!wanted) return 'true';
return field('{{{_flow.JIRA_REQUEST_TYPE_FIELD}}}').toLowerCase() === wanted ? 'true' : 'false';

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// Personio employee ID already stored on the work item, if any.
return json(field('{{{_flow.JIRA_PERSONIO_PERSON_ID_FIELD}}}'));

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

const hours = (v) => v.replace(',', '.');

const mapTo = (map, value) => {
  if (!value || !map.trim()) return value;
  const hit = map.split(';').filter((pair) => pair.includes('='))
    .map((pair) => [pair.slice(0, pair.indexOf('=')).trim(), pair.slice(pair.indexOf('=') + 1).trim()])
    .find((pair) => pair[0].toLowerCase() === value.toLowerCase());
  return hit ? hit[1] : '';
};

// Every problem with the request, joined into one sentence for the Jira comment. Empty means valid.
const errors = [];
const personId = field('{{{_flow.JIRA_PERSONIO_PERSON_ID_FIELD}}}');
const email = field('{{{_flow.JIRA_EMPLOYEE_EMAIL_FIELD}}}');
if (!personId && !email) errors.push('Neither a Personio employee ID nor an employee email is set (Jira field {{{_flow.JIRA_EMPLOYEE_EMAIL_FIELD}}})');
const values = ['{{{_flow.JIRA_POSITION_FIELD}}}', '{{{_flow.JIRA_DEPARTMENT_FIELD}}}', '{{{_flow.JIRA_OFFICE_FIELD}}}',
  '{{{_flow.JIRA_LEGAL_ENTITY_FIELD}}}', '{{{_flow.JIRA_WEEKLY_HOURS_FIELD}}}', '{{{_flow.JIRA_SUPERVISOR_FIELD}}}'].map(field);
if (!values.some(Boolean)) errors.push('The request does not change any employment attribute');
const weekly = hours(field('{{{_flow.JIRA_WEEKLY_HOURS_FIELD}}}'));
if (weekly && !/^\d+(\.\d+)?$/.test(weekly)) errors.push('Weekly working hours "' + weekly + '" is not a number');
const mapped = (label, value, map, name) => { if (value && !mapTo(map, value)) errors.push(label + ' "' + value + '" has no entry in ' + name); };
mapped('Department', field('{{{_flow.JIRA_DEPARTMENT_FIELD}}}'), "{{{_flow.DEPARTMENT_ID_MAP}}}", 'DEPARTMENT_ID_MAP');
mapped('Office', field('{{{_flow.JIRA_OFFICE_FIELD}}}'), "{{{_flow.OFFICE_ID_MAP}}}", 'OFFICE_ID_MAP');
mapped('Legal entity', field('{{{_flow.JIRA_LEGAL_ENTITY_FIELD}}}'), "{{{_flow.LEGAL_ENTITY_ID_MAP}}}", 'LEGAL_ENTITY_ID_MAP');
return json(errors.join('; '));

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// The Personio employee ID stored on the work item wins; the employee email is the fallback.
const personId = field('{{{_flow.JIRA_PERSONIO_PERSON_ID_FIELD}}}');
if (personId) return 'id=' + encodeURIComponent(personId);
const email = field('{{{_flow.JIRA_EMPLOYEE_EMAIL_FIELD}}}');
return email ? 'email=' + encodeURIComponent(email) : '';

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// Human readable form of the lookup, for Jira comments.
const personId = field('{{{_flow.JIRA_PERSONIO_PERSON_ID_FIELD}}}');
if (personId) return json('Personio employee ID ' + personId);
return json('email ' + field('{{{_flow.JIRA_EMPLOYEE_EMAIL_FIELD}}}'));

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

const hours = (v) => v.replace(',', '.');

const mapTo = (map, value) => {
  if (!value || !map.trim()) return value;
  const hit = map.split(';').filter((pair) => pair.includes('='))
    .map((pair) => [pair.slice(0, pair.indexOf('=')).trim(), pair.slice(pair.indexOf('=') + 1).trim()])
    .find((pair) => pair[0].toLowerCase() === value.toLowerCase());
  return hit ? hit[1] : '';
};

// The employment attributes this request changes, as JSON members without braces. Attributes the request leaves
// empty are not included, so Personio keeps their current values. The supervisor is added by the update action.
const out = {};
const position = field('{{{_flow.JIRA_POSITION_FIELD}}}');
if (position) out.position = { title: position };
const department = mapTo("{{{_flow.DEPARTMENT_ID_MAP}}}", field('{{{_flow.JIRA_DEPARTMENT_FIELD}}}'));
if (department) out.org_units = [{ type: 'department', id: department }];
const office = mapTo("{{{_flow.OFFICE_ID_MAP}}}", field('{{{_flow.JIRA_OFFICE_FIELD}}}'));
if (office) out.office = { id: office };
const legalEntity = mapTo("{{{_flow.LEGAL_ENTITY_ID_MAP}}}", field('{{{_flow.JIRA_LEGAL_ENTITY_FIELD}}}'));
if (legalEntity) out.legal_entity = { id: legalEntity };
const weekly = hours(field('{{{_flow.JIRA_WEEKLY_HOURS_FIELD}}}'));
if (/^\d+(\.\d+)?$/.test(weekly)) out.weekly_working_hours = Number(weekly);
return JSON.stringify(out).slice(1, -1);

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

const hours = (v) => v.replace(',', '.');

// The requested changes in words, for the Jira comments.
const parts = [];
const add = (label, value) => { if (value) parts.push(label + ': ' + value); };
add('position', field('{{{_flow.JIRA_POSITION_FIELD}}}'));
add('department', field('{{{_flow.JIRA_DEPARTMENT_FIELD}}}'));
add('office', field('{{{_flow.JIRA_OFFICE_FIELD}}}'));
add('legal entity', field('{{{_flow.JIRA_LEGAL_ENTITY_FIELD}}}'));
add('weekly working hours', hours(field('{{{_flow.JIRA_WEEKLY_HOURS_FIELD}}}')));
add('supervisor', field('{{{_flow.JIRA_SUPERVISOR_FIELD}}}'));
return json(parts.join(', '));

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

const v = field('{{{_flow.JIRA_SUPERVISOR_FIELD}}}');
return json(v);

const issue = (scope && scope.issue) || (scope && scope.payload && scope.payload.issue) || {};
const fields = issue.fields || {};
// Option -> value, user -> emailAddress, request type -> name, list -> first entry.
const flat = (v) => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.length ? flat(v[0]) : '';
  if (typeof v === 'object') return flat(v.value !== undefined ? v.value : v.emailAddress !== undefined ? v.emailAddress : v.requestType ? v.requestType.name : v.name);
  return String(v).trim();
};
const field = (id) => (id ? flat(fields[id]) : '');
const json = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\r?\n/g, '\\n').replace(/\t/g, '\\t');

// The next action must find exactly one person to continue. With a supervisor requested that is the supervisor;
// without one the query is unfiltered and returns any person, and the body leaves the supervisor out.
const email = field('{{{_flow.JIRA_SUPERVISOR_FIELD}}}');
return email ? 'email=' + encodeURIComponent(email) + '&' : '';

